<?php
namespace App\Http\Controllers\UserArea; use App\Http\Controllers\Controller; use App\Models\{AuditLog,Booking,Review}; use Illuminate\Http\{RedirectResponse,Request};
class ReviewController extends Controller {public function store(Request $r,Booking $booking):RedirectResponse{abort_unless($booking->user_id===$r->user()->id,403);abort_unless(in_array($booking->status,['completed','checked_out'],true)||filled($booking->checked_out_at),422);abort_if(Review::where('booking_id',$booking->id)->exists(),422);$d=$r->validate(['rating'=>'required|integer|min:1|max:5','title'=>'nullable|string|max:120','body'=>'required|string|min:20|max:3000']);$review=Review::create($d+['booking_id'=>$booking->id,'user_id'=>$r->user()->id,'status'=>'pending']);AuditLog::record('review.submitted',$review);return back()->with('success','Your verified-stay review was submitted for moderation.');}}
